import{_ as l,a0 as a,w as p,s as n,ao as S,I as s,x as o,a1 as r,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"FreeDOS 如何啓動 | LCTT x X-CMD","titleTemplate":false,"description":"FreeDOS 如何啓動 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"FreeDOS 如何啓動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"FreeDOS 如何啓動 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210608 How FreeDOS boots","title":"FreeDOS 如何啓動","tag":"202106","desc":""},"relativePath":"202106/20210608 How FreeDOS boots.md","filePath":"[post].md"}'),i={name:"202106/20210608 How FreeDOS boots.md"};function O(c,e,u,m,D,F){const t=a("Link");return p(),n("div",null,[e[15]||(e[15]=S('<h1 id="freedos-如何啓動" tabindex="-1">FreeDOS 如何啓動 <a class="header-anchor" href="#freedos-如何啓動" aria-label="Permalink to “FreeDOS 如何啓動”">​</a></h1><blockquote><p>概述你的計算機如何引導和啓動一個像 FreeDOS 這樣的簡單操作系統。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/20/140809fpkrcnow8npnow8p.jpg" alt=""></p><p>在使用 DOS 計算機的過程中，我很欣賞的一點是，引導過程相對容易理解。在 DOS 中沒有太多的變動組件。而今天，我想和大家分享一下電腦是如何引導和啓動像 FreeDOS 這樣的簡單操作系統的概況。</p><h3 id="初始引導" tabindex="-1">初始引導 <a class="header-anchor" href="#初始引導" aria-label="Permalink to “初始引導”">​</a></h3><p>當你打開計算機的電源時，系統會進行一些自我檢查，如驗證內存和其他組件。這被稱為<ruby>開機自檢<rt>Power On Self Test</rt></ruby>（POST）。POST 之後，計算機使用一個硬編碼指令，告訴它在哪裏找到加載操作系統的指令。這就是“<ruby>引導加載程序<rt>boot loader</rt></ruby>”，通常它將試圖找到硬盤上的<ruby>主引導記錄<rt>Master Boot Record</rt></ruby>（MBR）。然後，MBR 加載主操作系統，在這裏就是 FreeDOS。</p><p>這個定位一個信息以便計算機能夠加載操作系統的下一個部分的過程被稱為“<ruby>引導<rt>bootstrapping</rt></ruby>”，來自於“<ruby>通過你自己的努力振作起來<rt>picking yourself up by your bootstraps</rt></ruby>”的古老説法。正是從這個用法中，我們採用了“<ruby>引導<rt>boot</rt></ruby>”一詞來表示啓動你的計算機。</p><h3 id="內核" tabindex="-1">內核 <a class="header-anchor" href="#內核" aria-label="Permalink to “內核”">​</a></h3><p>當計算機加載 FreeDOS 內核時，內核所做的第一件事就是識別用户所表示要使用的任何參數。它被保存在一個叫做 <code>FDCONFIG.SYS</code> 的文件中，與內核保存在同一個根目錄下。如果 <code>FDCONFIG.SYS</code> 不存在，那麼 FreeDOS 的內核就會尋找一個叫做 <code>CONFIG.SYS</code> 的替代文件。</p><p>如果你在 20 世紀 80 年代或 90 年代使用過 DOS，你可能對 <code>CONFIG.SYS</code> 文件很熟悉。從 1999 年起，FreeDOS 首先尋找 <code>FDCONFIG.SYS</code>，以防你的 DOS 系統與其他 DOS（如 MS-DOS）做了 <em>雙啓動</em>。請注意，MS-DOS 只使用 <code>CONFIG.SYS</code> 文件。因此，如果你用同一個硬盤同時啓動 FreeDOS 和 MS-DOS，MS-DOS 使用 <code>CONFIG.SYS</code> 來配置自己，而 FreeDOS 則使用 <code>FDCONFIG.SYS</code>。這樣一來，雙方都可以使用自己的配置。</p><p><code>FDCONFIG.SYS</code> 可以包含一些配置設置，其中之一是 <code>SHELL=</code> 或 <code>SHELLHIGH=</code>。任何一個都會指示內核加載這個程序作為用户的交互式 shell。</p><p>如果 <code>FDCONFIG.SYS</code> 和 <code>CONFIG.SYS</code> 都不存在，那麼內核就會假定幾個默認值，包括在哪裏找到 shell。如果你在啓動 FreeDOS 系統時看到 “Bad or missing Command Interpreter” 的信息，這意味着 <code>SHELL=</code> 或 <code>SHELLHIGH=</code> 指向了一個在你係統中不存在的 shell 程序。</p><p><img src="https://opensource.com/sites/default/files/uploads/bad-missing-command.png" alt="Bad or missing Command Interpreter" title="Bad or missing Command Interpreter"></p><p>你可以通過查看 <code>SHELL=</code> 或 <code>SHELLHIGH=</code> 行來調試這個問題。如果做不到這一點，請確保你在 FreeDOS 系統的根目錄下有一個名為 <code>COMMAND.COM</code> 的程序。它就是 <em>shell</em>，我接下來會講到它。</p><h3 id="shell" tabindex="-1">shell <a class="header-anchor" href="#shell" aria-label="Permalink to “shell”">​</a></h3><p>在 DOS 系統中，“shell” 一詞通常是指一個命令列解釋器：一個交互式程序，它從用户那裏讀取指令，然後執行它們。在這裏，FreeDOS 的 shell 與 Linux 的 Bash shell 相似。</p><p>除非你用 <code>SHELL=</code> 或 <code>SHELLHIGH=</code> 要求內核加載一個不同的 shell，否則 DOS 上的標準命令列 shell 被稱為 <code>COMMAND.COM</code>。當 <code>COMMAND.COM</code> 啓動時，它也尋找一個文件來配置自己。默認情況下，<code>COMMAND.COM</code> 會在根目錄下尋找一個名為 <code>AUTOEXEC.BAT</code> 的文件。<code>AUTOEXEC.BAT</code> 是一個“批處理文件”，它包含一組啓動時運行的指令，大致類似於 Linux 上 Bash 啓動時讀取的 <code>~/.bashrc</code> “資源文件”。</p><p>你可以在 <code>FDCONFIG.SYS</code> 文件中用 <code>SHELL=</code> 或 <code>SHELLHIGH=</code> 改變 shell 以及 shell 的啓動文件。FreeDOS 1.3 RC4 安裝程序將系統設置為讀取 <code>FDAUTO.BAT</code> 而不是 <code>AUTOEXEC.BAT</code>。這與內核讀取另一個配置文件的原因相同；你可以在硬盤上用另一個 DOS 雙啓動 FreeDOS。FreeDOS 將使用 <code>FDAUTO.BAT</code> 而 MS-DOS 將使用 <code>AUTOEXEC.BAT</code>。</p><p>如果沒有像 <code>AUTOEXEC.BAT</code> 這樣的啓動文件，shell 將簡單地提示用户輸入日期和時間。</p><p><img src="https://opensource.com/sites/default/files/uploads/no-autoexec.png" alt="Without AUTOEXEC.BAT, the shell will prompt for date and time" title="Without AUTOEXEC.BAT, the shell will prompt for date and time"></p><p>就是這些了。當 FreeDOS 加載了內核，而內核也加載了 shell，FreeDOS 就準備好讓用户輸入命令了。</p><p><img src="https://opensource.com/sites/default/files/uploads/freedos-boot.png" alt="FreeDOS is ready for you to enter your first command" title="FreeDOS is ready for you to enter your first command"></p><hr>',23)),s("p",null,[e[1]||(e[1]=o("via: ",-1)),r(t,{href:"https://opensource.com/article/21/6/freedos-boots"},{default:d(()=>[...e[0]||(e[0]=[o("https://opensource.com/article/21/6/freedos-boots",-1)])]),_:1})]),s("p",null,[e[6]||(e[6]=o("作者：",-1)),r(t,{href:"https://opensource.com/users/jim-hall"},{default:d(()=>[...e[2]||(e[2]=[o("Jim Hall",-1)])]),_:1}),e[7]||(e[7]=o(" 選題：",-1)),r(t,{href:"https://github.com/lujun9972"},{default:d(()=>[...e[3]||(e[3]=[o("lujun9972",-1)])]),_:1}),e[8]||(e[8]=o(" 譯者：",-1)),r(t,{href:"https://github.com/geekpi"},{default:d(()=>[...e[4]||(e[4]=[o("geekpi",-1)])]),_:1}),e[9]||(e[9]=o(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[5]||(e[5]=[o("wxy",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=o("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:d(()=>[...e[11]||(e[11]=[o("Linux中國",-1)])]),_:1}),e[14]||(e[14]=o(" 榮譽推出",-1))])])}const T=l(i,[["render",O]]);export{h as __pageData,T as default};
